CREATE TABLE `manga` (
  `id` int NOT NULL AUTO_INCREMENT,
  `title` varchar(200) COLLATE utf8mb4_general_ci NOT NULL,
  `slug` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `description` text COLLATE utf8mb4_general_ci,
  `cover_image` varchar(500) COLLATE utf8mb4_general_ci DEFAULT '/default-cover.jpg',
  `status` enum('ongoing','completed','hiatus') COLLATE utf8mb4_general_ci DEFAULT 'ongoing',
  `type` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'manga',
  `author` varchar(100) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `views` int DEFAULT '0',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `rating` decimal(3,2) DEFAULT '0.00',
  `rating_count` int DEFAULT '0',
  PRIMARY KEY (`id`),
  KEY `idx_status` (`status`),
  KEY `idx_views` (`views`),
  FULLTEXT KEY `idx_search` (`title`,`description`)
