INSERT INTO `manga` VALUES (1,'One Piece',NULL,'Follow Monkey D. Luffy and his pirate crew in search of the legendary treasure known as One Piece.','Assets/CoverImg/OPC.jpg','ongoing','manga','Eiichiro Oda',1500000,'2025-12-30 17:59:55','2025-12-31 16:53:53',9.00,700),(2,'Attack on Titan','attack-on-titan','Humanity lives inside cities surrounded by enormous walls that protect them from gigantic man-eating humanoids referred to as Titans.','Assets/CoverImg/aotImgC.jpg','completed','manga','Hajime Isayama',1200000,'2025-12-30 17:59:55','2026-01-01 05:35:38',9.83,0),(3,'Naruto',NULL,'Naruto Uzumaki, a young ninja who seeks recognition from his peers and dreams of becoming the Hokage.','Assets/CoverImg/NarutoC.jpg','completed','manga','Masashi Kishimoto',1800000,'2025-12-30 17:59:55','2025-12-30 19:09:24',0.00,0),(4,'Jujutsu Kaisen',NULL,'High school student Yuuji Itadori joins a secret organization of Jujutsu Sorcerers to eliminate a powerful Curse.','Assets/CoverImg/JJKC.jpg','ongoing','manga','Gege Akutami',900000,'2025-12-30 17:59:55','2025-12-30 19:08:01',0.00,0),(5,'Demon Slayer',NULL,'Tanjiro Kamado becomes a demon slayer after his family is slaughtered and his sister is turned into a demon.','Assets/CoverImg/DSC.jpg','completed','manga','Koyoharu Gotouge',1100000,'2025-12-30 17:59:55','2025-12-30 19:09:36',0.00,0),(13,'JoJo\'s Bizarre Adventure: Phantom Blood','jojos-bizarre-adventure-phantom-blood','While the gold rush takes Europe by storm, a young Jonathan Joestar lives a life of luxury with his father at their estate in Liverpool, England. Jonathan, known by his peers as JoJo, spends his days playing the part of a gentleman and living a carefree life. However, those peaceful days soon came to an end when Dio Brando intrudes upon him.','Assets/CoverImg/jojo1.png','completed','manga','Hirohiko Araki',0,'2019-01-20 20:02:07','2026-01-04 10:22:06',0.00,0),(14,'JoJo\'s Bizarre Adventure: Battle Tendency','jojos-bizarre-adventure-battle-tendency','Taking place in 1938-1939, the story follows the misadventures of Joseph Joestar, grandson of Jonathan. Joseph\'s journey involves mastering his innate Ripple abilities in order to combat hostile, ancient superbeings named the Pillar Men, creators of the Stone Mask, that plot to achieve their final evolutions.\n','Assets/CoverImg/jojo2.jpg','completed','manga','Hirohiko Araki',0,'2026-01-03 20:02:07','2026-01-04 10:11:00',0.00,0),(15,'JoJo\'s Bizarre Adventure: Stardust Crusaders','jojos-bizarre-adventure-stardust-crusaders','From 1988 to 1989,the story follows Jotaro Kujo and his friends as they journey from Tokyo to Cairo to save his mother\'s life by defeating his family\'s resurrected archenemy, DIO.','Assets/CoverImg/jojo3.jpg','completed','manga',NULL,0,'2026-01-03 20:02:07','2026-01-04 10:09:50',0.00,0),(16,'JoJo\'s Bizarre Adventure: Diamond Is Unbreakable','jojos-bizarre-adventure-diamond-is-unbreakable','In 1999, the Arrow, manifesting latent Stand abilities, travels throughout Morioh, Japan. Meanwhile, high school student Josuke Higashikata, the illegitimate son of Joseph Joestar, seeks out the culprits of a series of homicides along with his friends and Jotaro Kujo.\n','Assets/CoverImg/jojo4.jpg','completed','manga',NULL,0,'2026-01-03 20:02:07','2026-01-04 10:20:17',0.00,0),(17,'JoJo\'s Bizarre Adventure: Golden Wind','jojos-bizarre-adventure-golden-wind','Set in Italy in the year 2001, the story follows Giorno Giovanna and his dream to rise within the Neapolitan mafia and defeat the boss of Passione, the most powerful and influential gang, in order to become a \"gang star.\" With the aid of a capo and his men, and fueled by his own resolve, Giorno sets out to fulfill his goal of absolving the mafia of its corruption.','Assets/CoverImg/jojo5.jpg','completed','manga',NULL,0,'2026-01-03 20:02:07','2026-01-04 10:18:47',0.00,0),(18,'JoJo\'s Bizarre Adventure: Stone Ocean','jojos-bizarre-adventure-stone-ocean','Set in Florida in the year 2011, Jolyne Cujoh, daughter of Jotaro, is wrongfully accused of a crime she didn\'t commit and sent to a maximum-security prison. While imprisoned, she struggles within a longstanding plot agreed between deceased villain DIO and ideologue Enrico Pucci.\n','Assets/CoverImg/jojo6.jpg','completed','manga',NULL,0,'2026-01-03 20:02:07','2026-01-04 10:10:20',0.00,0),(19,'Steel Ball Run','steel-ball-run','Steel Ball Run marks the start of a second continuity entirely separate from the events of Parts 1-6. Despite this, the story retains several core features of JoJo, including Stands, as well as numerous references to the original continuity, such as character names.','/Assets/CoverImg/jojo7.jpg','completed','manga','',0,'2026-01-07 00:49:25','2026-01-07 00:58:57',0.00,0),(20,'JoJolion','jojolion','The story begins in 2011 and follows Josuke Higashikata, a young man afflicted by retrograde amnesia, in his search to uncover his identity in Morioh Town, a Japanese coastal town affected by the Tohoku earthquake. However, his digging pulls him and his adoptive family into the unfinished business between his previous life and an impending inhuman threat.\n','Assets/CoverImg/jojo8.png','completed','manga','Hirohiko Araki',0,'2026-01-03 20:02:07','2026-01-04 10:10:43',0.00,0),(21,'The JOJOLands','the-jojolands','In contemporary Hawaii, Jodio Joestar, a 15-year-old boy living in Honolulu, aspires to become extremely rich by reaching the apex of the world\'s mechanisms. As for what he plans to do to achieve his goals, an unpredictable story unfolds in the islands woven with light and shadow.\n','Assets/CoverImg/jojo9.jpg','ongoing','manga','Hirohiko Araki',0,'2026-01-03 20:02:07','2026-01-04 10:10:31',0.00,0),(23,'mmmmm','mmmmm','asdsadad','Assets/CoverImg/aotImgC.jpg','hiatus','manga','',1111,'2026-01-07 01:00:15','2026-01-07 01:00:15',0.00,0);
/*!40000 ALTER TABLE `manga` ENABLE KEYS */;
UNLOCK TABLES;

